CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE context_request (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,purpose text NOT NULL,subject_type text NOT NULL,subject_id text NOT NULL,audience jsonb NOT NULL,time_horizon jsonb NOT NULL,required_sources jsonb NOT NULL,status text NOT NULL DEFAULT 'requested',requested_by uuid NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE context_source_profile (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,name text NOT NULL,gateway_key text NOT NULL,source_class text NOT NULL,freshness_policy jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',version integer NOT NULL DEFAULT 1,UNIQUE(id,tenant_id),UNIQUE(tenant_id,gateway_key,version));
CREATE TABLE context_assembly_plan (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,request_id uuid NOT NULL,required_profile_ids jsonb NOT NULL,optional_profile_ids jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',executed_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(request_id,tenant_id) REFERENCES context_request(id,tenant_id));
CREATE TABLE source_eligibility_decision (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plan_id uuid NOT NULL,source_profile_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN('eligible','forbidden','unavailable','out_of_scope')),reason text NOT NULL,principal_id uuid NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,plan_id,source_profile_id),FOREIGN KEY(plan_id,tenant_id) REFERENCES context_assembly_plan(id,tenant_id),FOREIGN KEY(source_profile_id,tenant_id) REFERENCES context_source_profile(id,tenant_id));
CREATE TABLE context_snapshot (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,request_id uuid NOT NULL,snapshot_version integer NOT NULL,status text NOT NULL DEFAULT 'draft',completeness numeric CHECK(completeness BETWEEN 0 AND 1),confidence numeric CHECK(confidence BETWEEN 0 AND 1),issued_by uuid,issued_at timestamptz,retired_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,request_id,snapshot_version),FOREIGN KEY(request_id,tenant_id) REFERENCES context_request(id,tenant_id));
CREATE TABLE context_reference (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,snapshot_id uuid NOT NULL,source_profile_id uuid NOT NULL,source_type text NOT NULL,source_id text NOT NULL,source_version text,observed_at timestamptz NOT NULL,freshness_state text NOT NULL,permission_decision_id uuid NOT NULL,lineage jsonb NOT NULL DEFAULT '{}',UNIQUE(id,tenant_id),UNIQUE(tenant_id,snapshot_id,source_profile_id,source_type,source_id,source_version),FOREIGN KEY(snapshot_id,tenant_id) REFERENCES context_snapshot(id,tenant_id),FOREIGN KEY(source_profile_id,tenant_id) REFERENCES context_source_profile(id,tenant_id),FOREIGN KEY(permission_decision_id,tenant_id) REFERENCES source_eligibility_decision(id,tenant_id));
CREATE TABLE context_citation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,reference_id uuid NOT NULL,locator text NOT NULL,excerpt text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,reference_id,locator),FOREIGN KEY(reference_id,tenant_id) REFERENCES context_reference(id,tenant_id));
CREATE TABLE context_contradiction (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,snapshot_id uuid NOT NULL,left_reference_id uuid NOT NULL,right_reference_id uuid NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',disposition text,decided_by uuid,decided_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(snapshot_id,tenant_id) REFERENCES context_snapshot(id,tenant_id),FOREIGN KEY(left_reference_id,tenant_id) REFERENCES context_reference(id,tenant_id),FOREIGN KEY(right_reference_id,tenant_id) REFERENCES context_reference(id,tenant_id));
CREATE TABLE context_redaction (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,reference_id uuid NOT NULL,field_path text NOT NULL,reason text NOT NULL,policy_ref text NOT NULL,applied_by uuid NOT NULL,applied_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,reference_id,field_path),FOREIGN KEY(reference_id,tenant_id) REFERENCES context_reference(id,tenant_id));
CREATE TABLE context_indicator (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,snapshot_id uuid NOT NULL,indicator_type text NOT NULL,value numeric,detail jsonb NOT NULL,calculation_version text NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,snapshot_id,indicator_type),FOREIGN KEY(snapshot_id,tenant_id) REFERENCES context_snapshot(id,tenant_id));
CREATE TABLE synthesis_packet (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,snapshot_id uuid NOT NULL,view_type text NOT NULL CHECK(view_type IN('executive','operational')),content jsonb NOT NULL,citations jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',issued_by uuid,issued_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(snapshot_id,tenant_id) REFERENCES context_snapshot(id,tenant_id));
CREATE TABLE context_advisory_request (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,snapshot_id uuid NOT NULL,advisory_type text NOT NULL CHECK(advisory_type IN('nova','pops')),request_text text NOT NULL,response jsonb,citations jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'requested',requested_by uuid NOT NULL,idempotency_key text NOT NULL,completed_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(snapshot_id,tenant_id) REFERENCES context_snapshot(id,tenant_id));
CREATE TABLE context_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(id,tenant_id));
CREATE INDEX idx_context_request_status ON context_request(tenant_id,status); CREATE INDEX idx_snapshot_request ON context_snapshot(tenant_id,request_id,snapshot_version DESC); CREATE INDEX idx_reference_source ON context_reference(tenant_id,source_type,source_id); CREATE INDEX idx_contradiction_open ON context_contradiction(tenant_id,status) WHERE status='open'; CREATE INDEX idx_context_outbox ON context_outbox(status,created_at) WHERE status='pending';
CREATE OR REPLACE FUNCTION prevent_context_self_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE request_actor uuid; BEGIN IF NEW.status='issued' THEN SELECT r.requested_by INTO request_actor FROM context_snapshot s JOIN context_request r ON r.id=s.request_id AND r.tenant_id=s.tenant_id WHERE s.id=NEW.snapshot_id AND s.tenant_id=NEW.tenant_id; IF request_actor IS NULL OR NEW.issued_by IS NULL OR NEW.issued_by=request_actor THEN RAISE EXCEPTION 'context requester cannot issue synthesis packet for the same request chain'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_context_self_approval BEFORE INSERT OR UPDATE ON synthesis_packet FOR EACH ROW EXECUTE FUNCTION prevent_context_self_approval();
CREATE OR REPLACE FUNCTION protect_context_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='source_eligibility_decision' OR TG_TABLE_NAME='context_redaction' OR (TG_TABLE_NAME='context_request' AND OLD.status='authorized') OR (TG_TABLE_NAME='context_assembly_plan' AND OLD.executed_at IS NOT NULL) OR (TG_TABLE_NAME='context_snapshot' AND OLD.status IN('issued','retired')) OR (TG_TABLE_NAME='context_reference' AND EXISTS(SELECT 1 FROM context_snapshot s WHERE s.id=OLD.snapshot_id AND s.tenant_id=OLD.tenant_id AND s.status IN('issued','retired'))) OR (TG_TABLE_NAME='context_citation' AND EXISTS(SELECT 1 FROM context_reference r JOIN context_snapshot s ON s.id=r.snapshot_id AND s.tenant_id=r.tenant_id WHERE r.id=OLD.reference_id AND r.tenant_id=OLD.tenant_id AND s.status IN('issued','retired'))) OR (TG_TABLE_NAME='context_contradiction' AND OLD.status='disposed') OR (TG_TABLE_NAME='context_indicator' AND EXISTS(SELECT 1 FROM context_snapshot s WHERE s.id=OLD.snapshot_id AND s.tenant_id=OLD.tenant_id AND s.status IN('issued','retired'))) OR (TG_TABLE_NAME='synthesis_packet' AND OLD.status='issued') OR (TG_TABLE_NAME='context_advisory_request' AND OLD.status='completed') THEN RAISE EXCEPTION 'issued context record is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_request_immutable BEFORE UPDATE OR DELETE ON context_request FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_plan_immutable BEFORE UPDATE OR DELETE ON context_assembly_plan FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_eligibility_immutable BEFORE UPDATE OR DELETE ON source_eligibility_decision FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_snapshot_immutable BEFORE UPDATE OR DELETE ON context_snapshot FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_reference_immutable BEFORE UPDATE OR DELETE ON context_reference FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_citation_immutable BEFORE UPDATE OR DELETE ON context_citation FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_contradiction_immutable BEFORE UPDATE OR DELETE ON context_contradiction FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_redaction_immutable BEFORE UPDATE OR DELETE ON context_redaction FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_indicator_immutable BEFORE UPDATE OR DELETE ON context_indicator FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_packet_immutable BEFORE UPDATE OR DELETE ON synthesis_packet FOR EACH ROW EXECUTE FUNCTION protect_context_record(); CREATE TRIGGER trg_advisory_immutable BEFORE UPDATE OR DELETE ON context_advisory_request FOR EACH ROW EXECUTE FUNCTION protect_context_record();
ALTER TABLE context_request ENABLE ROW LEVEL SECURITY; ALTER TABLE context_source_profile ENABLE ROW LEVEL SECURITY; ALTER TABLE context_assembly_plan ENABLE ROW LEVEL SECURITY; ALTER TABLE source_eligibility_decision ENABLE ROW LEVEL SECURITY; ALTER TABLE context_snapshot ENABLE ROW LEVEL SECURITY; ALTER TABLE context_reference ENABLE ROW LEVEL SECURITY; ALTER TABLE context_citation ENABLE ROW LEVEL SECURITY; ALTER TABLE context_contradiction ENABLE ROW LEVEL SECURITY; ALTER TABLE context_redaction ENABLE ROW LEVEL SECURITY; ALTER TABLE context_indicator ENABLE ROW LEVEL SECURITY; ALTER TABLE synthesis_packet ENABLE ROW LEVEL SECURITY; ALTER TABLE context_advisory_request ENABLE ROW LEVEL SECURITY; ALTER TABLE context_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY context_request_tenant ON context_request USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY source_profile_tenant ON context_source_profile USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY assembly_plan_tenant ON context_assembly_plan USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY eligibility_tenant ON source_eligibility_decision USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY snapshot_tenant ON context_snapshot USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY reference_tenant ON context_reference USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY citation_tenant ON context_citation USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY contradiction_tenant ON context_contradiction USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY redaction_tenant ON context_redaction USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY indicator_tenant ON context_indicator USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY packet_tenant ON synthesis_packet USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY advisory_tenant ON context_advisory_request USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY outbox_tenant ON context_outbox USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid);
